package com.grafkom.viewing3d;
import org.joml.*;import org.lwjgl.glfw.*;import org.lwjgl.opengl.*;import org.lwjgl.system.*;import java.nio.*;import java.nio.file.*;import static org.lwjgl.glfw.GLFW.*;import static org.lwjgl.opengl.GL11.*;import static org.lwjgl.opengl.GL13.GL_TEXTURE1;
import static org.lwjgl.opengl.GL13.glActiveTexture;
import static org.lwjgl.system.MemoryUtil.*;
public final class Main {
 private long window;private int width=1100,height=720,frameCount=0;private double fpsStart;private boolean blinn=true,smooth=true,depth=true,cull=false,mip=true;private ShaderProgram scene,depthShader;private Mesh sphere,ground;private Texture2D texture;private ShadowMapFBO shadow;
 public static void main(String[] args){new Main().run();}
 private void run(){init();loop();cleanup();}
 private void init(){if(!glfwInit())throw new IllegalStateException("GLFW init failed");glfwWindowHint(GLFW_CONTEXT_VERSION_MAJOR,3);glfwWindowHint(GLFW_CONTEXT_VERSION_MINOR,3);glfwWindowHint(GLFW_OPENGL_PROFILE,GLFW_OPENGL_CORE_PROFILE);window=glfwCreateWindow(width,height,"3D Visual Realism Suite | B/F/Z/C/T",NULL,NULL);if(window==NULL)throw new IllegalStateException("Window creation failed");glfwMakeContextCurrent(window);glfwSwapInterval(0);GL.createCapabilities();fpsStart=glfwGetTime();glEnable(GL_DEPTH_TEST);glClearColor(.10f,.12f,.16f,1f);glfwSetFramebufferSizeCallback(window,(w,x,y)->{width=x;height=y;glViewport(0,0,x,y);});glfwSetKeyCallback(window,(w,key,scancode,action,mods)->{if(action==GLFW_PRESS){if(key==GLFW_KEY_ESCAPE)glfwSetWindowShouldClose(w,true);if(key==GLFW_KEY_B)blinn=!blinn;if(key==GLFW_KEY_F)smooth=!smooth;if(key==GLFW_KEY_Z)depth=!depth;if(key==GLFW_KEY_C)cull=!cull;if(key==GLFW_KEY_T){mip=!mip;if(texture!=null)texture.setMipmapped(mip);}}});
   scene=new ShaderProgram(read("src/main/resources/shaders/scene.vert"),read("src/main/resources/shaders/scene.frag"));depthShader=new ShaderProgram(read("src/main/resources/shaders/depth.vert"),read("src/main/resources/shaders/depth.frag"));sphere=Mesh.sphere(36,48);ground=Mesh.plane();texture=new Texture2D("assets/checker.png");shadow=new ShadowMapFBO();}
 private String read(String path){try{return Files.readString(Path.of(path));}catch(Exception e){throw new IllegalStateException("Cannot read "+path,e);}}
 private void loop(){Vector3f light=new Vector3f(-2.5f,5f,2f),eye=new Vector3f(4f,3.2f,6f);Matrix4f view=new Matrix4f().lookAt(eye,new Vector3f(0,.7f,0),new Vector3f(0,1,0));Matrix4f lightSpace=new Matrix4f().ortho(-7,7,-7,7,.1f,20f).mul(new Matrix4f().lookAt(light,new Vector3f(0,0,0),new Vector3f(0,1,0)));
    while(!glfwWindowShouldClose(window)){glfwPollEvents();HSRManager.setupDepthTest(true);shadow.bindForWriting();glClear(GL_DEPTH_BUFFER_BIT);depthShader.use();depthShader.set("lightSpace",lightSpace);drawDepth(new Matrix4f().translate(0,1,0),sphere);drawDepth(new Matrix4f(),ground);shadow.unbind(width,height);HSRManager.setupDepthTest(depth);HSRManager.setupBackFaceCulling(cull);glClear(GL_COLOR_BUFFER_BIT|GL_DEPTH_BUFFER_BIT);scene.use();scene.set("view",view);scene.set("projection",new Matrix4f().perspective((float)java.lang.Math.toRadians(45),java.lang.Math.max(width,1)/(float)java.lang.Math.max(height,1),.1f,100f));scene.set("lightSpace",lightSpace);scene.set("lightPos",light);scene.set("viewPos",eye);scene.set("useBlinn",blinn?1:0);scene.set("flatMode",smooth?0:1);scene.set("shadowBias",.004f);scene.set("shadowMap",1);glActiveTexture(GL_TEXTURE1);glBindTexture(GL_TEXTURE_2D,shadow.texture());scene.set("imageTexture",0);scene.set("useTexture",1);scene.set("objectColor",new Vector3f(.75f,.42f,.18f));texture.bind(0);Matrix4f m=new Matrix4f().translate(0,1,0);scene.set("model",m);sphere.draw();scene.set("useTexture",0);scene.set("objectColor",new Vector3f(.75f,.75f,.75f));scene.set("model",new Matrix4f());ground.draw();glfwSwapBuffers(window);frameCount++;double now=glfwGetTime();if(now-fpsStart>=1.0){glfwSetWindowTitle(window,String.format("3D Visual Realism Suite | %.1f FPS | B/F/Z/C/T",frameCount/(now-fpsStart)));frameCount=0;fpsStart=now;}}
 }
 private void drawDepth(Matrix4f model,Mesh mesh){depthShader.set("model",model);mesh.draw();}
 private void cleanup(){if(texture!=null)texture.close();if(shadow!=null)shadow.close();glfwDestroyWindow(window);glfwTerminate();}
}
